def esc(s): return html.escape(str(s), quote=True)
def slugify(s): return re.sub(r'[^a-z0-9-]','',re.sub(r'\s+','-',s.lower()))[:44]
def logo(): return '<svg viewBox="0 0 164 195" width="22" aria-hidden="true"><path d="M117 194.5H0L12 73C17 67 21 65 29 64L35 0H152C158 4 161 7 164 13L153 120C149 127 145 130 136 131L131 185C128 190 125 193 117 195Z" fill="#01dc82"/><path d="M64 33L61 65H94L91 97H123L128 47C126 38 122 35 113 33H64Z" fill="#033330"/><path d="M37 148L42 98H75L72 130L104 131L101 162H50C42 159 40 156 37 148Z" fill="#033330"/></svg>'
STYLE='''<style>:root{--brand:#01dc82;--deep:#033330;--lime:#cfe66a;--red:#b3261e;--amber:#9a6700;--ink:#0f172a;--muted:#475569;--line:#e2e8f0;--bg:#fafaf9;--card:#fff;--serif:Newsreader,Georgia,serif;--sans:"Plus Jakarta Sans",system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.55}main{max-width:66rem;margin:auto;padding:3rem 1.5rem}header{display:flex;flex-direction:column;gap:1rem;margin-bottom:2rem}.wordmark{display:flex;align-items:center;gap:.6rem;font-weight:700;color:var(--deep)}h1,h2{font-family:var(--serif);color:var(--deep);font-weight:600}h1{font-size:2.1rem;margin:0}h2{font-size:1.35rem;margin:0 0 .45rem}h3{font-size:.9rem;margin:1rem 0 .25rem;color:var(--deep)}a{color:#087f58}.dek{max-width:55rem;color:var(--muted);font-size:1.02rem}.meta{font:.78rem ui-monospace,monospace;color:var(--muted)}section{display:flex;flex-direction:column;gap:1rem}.card{background:var(--card);border:1px solid var(--line);border-radius:.75rem;padding:1.4rem;margin:1rem 0}.badges{display:flex;flex-wrap:wrap;gap:.45rem;margin:.25rem 0 .8rem}.badge{font-size:.68rem;text-transform:uppercase;letter-spacing:.06em;font-weight:700;padding:.15rem .5rem;border-radius:.35rem;background:#f1f5f9;color:var(--muted)}.good{background:#dcfce7;color:#166534}.warn{background:#fef3c7;color:var(--amber)}.spec{background:#e2e8f0;color:#334155}.facts{font:.78rem ui-monospace,monospace;color:var(--muted);list-style:none;padding:0;margin:.5rem 0 1rem}.facts li{padding:.1rem 0}.diagram{border:1px solid var(--line);border-radius:.5rem;background:#fff;padding:1rem;margin:1rem 0}.diagram svg{display:block;max-width:100%;height:auto}.label{font:600 13px system-ui,sans-serif;fill:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}.callout{border-left:3px solid var(--amber);background:#fffbeb;color:#713f12;padding:.6rem .9rem;border-radius:.25rem;font-size:.9rem}.wins{margin:.5rem 0 0;padding-left:1.1rem}.wins li{margin:.25rem 0}.matrix{width:100%;border-collapse:collapse;font-size:.82rem}.matrix th,.matrix td{text-align:left;vertical-align:top;border-bottom:1px solid var(--line);padding:.55rem}.matrix th{color:var(--deep);font-weight:700}.source-list{padding-left:1.1rem}.source-list li{margin:.35rem 0}@media(max-width:600px){main{padding:2rem 1rem}.matrix{font-size:.72rem}}
</style>'''
def signal_svg(items):
    n=len(items); w=760; h=170; gap= w//n
    out=[f'<svg viewBox="0 0 {w} {h}" role="img" aria-label="Signal map showing four connected items"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#94a3b8"/></marker></defs><line x1="55" y1="85" x2="705" y2="85" stroke="#cbd5e1" stroke-width="2" marker-end="url(#arr)"/>']
    for i,it in enumerate(items):
        x=12+i*gap; y=45 if i%2==0 else 92; stroke='#01dc82' if i==0 else '#cbd5e1'
        out += [f'<rect x="{x}" y="{y}" width="145" height="36" rx="6" fill="#fff" stroke="{stroke}"/>',f'<text x="{x+72}" y="{y+22}" text-anchor="middle" class="label">{esc(it["title"][:22])}</text>']
    return ''.join(out)+'</svg>'
def page(lane):
    cards=[]
    for it in lane['items']:
        cards.append(f'<article class="card" id="{slugify(it["title"])}"><h2>{esc(it["title"])}</h2><div class="badges"><span class="badge good">selected</span><span class="badge">{esc(it["type"])}</span><span class="badge spec">{esc(it["published"])}</span></div><ul class="facts"><li>source: <a href="{esc(it["url"])}">{esc(it["url"])}</a></li></ul><div class="grid"><div><h3>What it is</h3><p>{esc(it["what"])}</p></div><div><h3>Why it matters</h3><p>{esc(it["why"])}</p></div><div><h3>Buildn / client use</h3><p>{esc(it["use"])}</p></div></div><div class="callout"><strong>Useful now:</strong> {esc(it["now"])}<br><strong>Caveat:</strong> {esc(it["caveat"])}</div><ul class="wins"><li><strong>Next:</strong> {esc(it["action"])}</li></ul></article>')
    sources=''.join(f'<li><a href="{esc(i["url"])}">{esc(i["title"])}</a></li>' for i in lane['items'])
    card_html=''.join(cards)
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Daily Ingest Dossier — {esc(lane["title"])} — {ISO}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{STYLE}</head><body><main><header><div class="wordmark">{logo()}<span>Buildn</span></div><div class="meta">DAILY INGEST DOSSIER · {ISO}</div><h1>{esc(lane["title"])}</h1><p class="dek">{esc(lane["thesis"])} {esc(lane["rationale"])}</p></header><section><article class="card"><h2>Signal map</h2><div class="diagram">{signal_svg(lane["items"])}</div><div class="callout">Selection rule: fresh primary-source signal, practical leverage, and a meaningful gap from the recent archive.</div></article>{card_html}<article class="card"><h2>Use-case matrix</h2><table class="matrix"><thead><tr><th>Theme</th><th>Buildn OS</th><th>Client work</th><th>Agent workflows</th><th>Personal leverage</th></tr></thead><tbody><tr><td>Execution</td><td>Bounded jobs + evidence</td><td>Reviewable delivery</td><td>Typed tools + gates</td><td>Safer delegation</td></tr><tr><td>Runtime</td><td>Pause/resume artifacts</td><td>Isolated workspaces</td><td>Identity + egress</td><td>Portable trials</td></tr><tr><td>Evaluation</td><td>Outcome scorecards</td><td>Regression checks</td><td>Replayable tasks</td><td>Time-boxed experiments</td></tr></tbody></table></article><article class="card"><h2>Top actions</h2><ol class="wins"><li>Run one bounded, read-only trial.</li><li>Capture evidence, cost, latency, and failures.</li><li>Promote only a repeatable control surface.</li></ol></article><article class="card"><h2>Source trail</h2><ul class="source-list">{sources}</ul></article></section></main></body></html>'

for lane in LANES:
    (OUT/f'daily-ingest-{lane["slug"]}-{DATE}.html').write_text(page(lane),encoding='utf-8')

ledger={"date":ISO,"generated_at":datetime.now(timezone.utc).isoformat(),"editorial_thesis":"Today’s strongest signal is the move from agent demos toward governed work surfaces: native IDE participation, disposable data planes, reproducible evidence, and human checkpoints in consequential workflows.","topic_groups":[]}
for lane in LANES:
    ledger['topic_groups'].append({"slug":lane['slug'],"title":lane['title'],"selection_rationale":lane['rationale'],"sources":[{"title":i['title'],"url":i['url'],"source_type":i['type'],"published_or_updated":i['published'],"why_selected":i['why'],"usefulness":i['use']} for i in lane['items']]})
(OUT/f'daily-ingest-{DATE}.json').write_text(json.dumps(ledger,indent=2),encoding='utf-8')

links=''.join(f'<li><a href="daily-ingest-{l["slug"]}-{DATE}.html">{esc(l["title"])}</a><br><span class="meta">{esc(l["rationale"])}</span></li>' for l in LANES)
overview=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Daily Ingest Dossier — {ISO}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{STYLE}</head><body><main><header><div class="wordmark">{logo()}<span>Buildn</span></div><div class="meta">ADAPTIVE DAILY INGEST · {ISO}</div><h1>From agent demos to governed work surfaces</h1><p class="dek">Today’s dossier follows the practical control surfaces that make delegation usable: native developer environments, isolated runtimes, evidence-bearing research, and approval-aware personal or physical workflows.</p></header><section><article class="card"><h2>Selected lanes</h2><ol class="wins">{links}</ol></article><article class="card"><h2>Executive readout</h2><div class="grid"><div><h3>1 · Developer surfaces</h3><p>IDE integrations are making agents interchangeable participants; protocols, sandboxing, and review become the durable layer.</p></div><div><h3>2 · Data plane</h3><p>Cloud desktops and scale-to-zero PostgreSQL make isolated, short-lived agent work easier to provision without abandoning policy.</p></div><div><h3>3 · Evidence</h3><p>Science and engineering workflows show the value of executable artifacts, provenance, and task-level evaluation.</p></div></div></article><article class="card"><h2>Top three to open first</h2><ol class="wins"><li><a href="daily-ingest-agent-ready-developer-surfaces-{DATE}.html">JetBrains Air + Copilot</a> — compare local and cloud task isolation.</li><li><a href="daily-ingest-agent-runtime-and-data-plane-{DATE}.html">AlloyDB Express</a> — measure disposable database setup for agent jobs.</li><li><a href="daily-ingest-evidence-bearing-science-and-evaluation-{DATE}.html">Claude Science</a> — copy its reproducible artifact contract.</li></ol></article><article class="card"><h2>Archive trail</h2><p><a href="../">All daily ingest</a> · <a href="ledger.json">Today’s source ledger</a></p></article></section></main></body></html>'
(OUT/'index.html').write_text(overview,encoding='utf-8')

# Durable coverage memory: preserve existing history, append this run, keep 45 days of item detail.
cp=PUBLIC/'topic-coverage.json'; cov=json.loads(cp.read_text()) if cp.exists() else {"schema_version":1,"rolling_theme_summary":{},"item_history":[]}
cov.setdefault('rolling_theme_summary',{}); hist=cov.setdefault('item_history',[])
for lane in LANES:
    s=cov['rolling_theme_summary'].setdefault(lane['slug'],{"title":lane['title'],"times_covered":0})
    s.update({"title":lane['title'],"times_covered":s.get('times_covered',0)+1,"last_covered":ISO,"last_selection_rationale":lane['rationale']})
    for i in lane['items']:
        hist.append({"date":ISO,"topic":lane['slug'],"title":i['title'],"url":i['url'],"source_type":i['type'],"rationale":i['why']})
cut=datetime.fromisoformat(ISO).date()-timedelta(days=45)
cov['item_history']=[x for x in hist if datetime.fromisoformat(x['date']).date()>=cut]
cov['last_successful_run']=ISO; cov['last_selection_rationale']=ledger['editorial_thesis']
cp.write_text(json.dumps(cov,indent=2),encoding='utf-8')
sp=PUBLIC/'seen-sources.json'; seen=json.loads(sp.read_text()) if sp.exists() else {"sources":{}}
seen.setdefault('sources',{})
for lane in LANES:
    for i in lane['items']:
        old=seen['sources'].get(i['url'],{}); seen['sources'][i['url']]={"first_seen":old.get('first_seen',ISO),"last_seen":ISO,"title":i['title']}
seen['updated_at']=datetime.now(timezone.utc).isoformat(); sp.write_text(json.dumps(seen,indent=2),encoding='utf-8')
print(OUT)
